<script setup>
import { ref, reactive, onMounted } from 'vue'
import { api, errorMessage } from '../services/api'
import { statuses } from '../domain'
import PageHeading from '../components/PageHeading.vue'
import AsyncState from '../components/AsyncState.vue'
const loading=ref(true), error=ref(''), stats=ref(null), filters=reactive({from:'',to:''})
async function load(){loading.value=true;error.value='';try{stats.value=(await api.get('/stats',{params:Object.fromEntries(Object.entries(filters).filter(([,v])=>v))})).data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
onMounted(load)
</script>
<template><PageHeading title="Estadísticas del repositorio" subtitle="Indicadores de producción y uso para el periodo seleccionado." /><q-form class="toolbar" @submit="load"><div class="form-grid"><q-input v-model="filters.from" type="date" outlined dense stack-label label="Desde" /><q-input v-model="filters.to" type="date" outlined dense stack-label label="Hasta" :min="filters.from" /></div><q-btn color="primary" unelevated label="Consultar periodo" type="submit" /></q-form><AsyncState :loading="loading" :error="error" @retry="load"><template v-if="stats"><p class="muted">Periodo: {{ stats.from }} — {{ stats.to }}</p><div class="metric-grid"><article v-for="m in [{label:'Recursos creados',value:stats.resources_created},{label:'Publicaciones',value:stats.published},{label:'Consultas',value:stats.views},{label:'Descargas',value:stats.downloads}]" :key="m.label" class="surface"><span class="metric">{{ m.value }}</span>{{ m.label }}</article></div><p v-if="stats.message" class="notice">{{ stats.message }}</p><div class="form-grid"><section class="surface"><h2>Recursos por estado</h2><p v-if="!Object.keys(stats.by_status).length" class="muted">Sin recursos creados en este periodo.</p><div v-for="(value,key) in stats.by_status" :key="key" class="chart-row"><span>{{ statuses[key]||key }}</span><div><div class="chart-bar" :style="{width:`${value/Math.max(1,stats.resources_created)*100}%`}" /></div><strong>{{ value }}</strong></div></section><section class="surface"><h2>Actividad y tipos de recurso</h2><dl class="metadata"><dt>Búsquedas</dt><dd>{{ stats.searches }}</dd><dt>Documentos</dt><dd>{{ stats.by_type.documento||0 }}</dd><dt>Proyectos</dt><dd>{{ stats.by_type.proyecto||0 }}</dd></dl></section></div></template></AsyncState></template>
